contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will try to call getFirstWithdrawalBonus on an arbitrary recipient address
    // The property: after the call, exactly one of two possibilities holds:
    // 1) call succeeded: claimedBonus(recipient) == true and address(c).balance decreased by 100 and this contract's balance may increase if recipient == address(this)
    // 2) call reverted: claimedBonus(recipient) unchanged (false) and address(c).balance unchanged

    // We cannot directly observe private rewardsForA, but we can observe claimedBonus via its public getter.

    function run(address payable recipient) public payable {
        require(true);

        // Fund contract c with some Ether so it can pay the 100 bonus when withdrawReward is called.
        // Only send if msg.value provided by the caller of run; require we have that balance first.
        if (msg.value > 0) {
            require(address(this).balance >= msg.value);
            (bool sent,) = address(c).call{value: msg.value}("\x00");
            // It's okay if this low-level call fails; the property will reason about balance changes below.
        }

        uint beforeBal = address(c).balance;
        bool beforeClaimed = c.claimedBonus(recipient);

        bool reverted;
        try c.getFirstWithdrawalBonus(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBal = address(c).balance;
        bool afterClaimed = c.claimedBonus(recipient);

        // General rule: if call reverted, contract balance and claimed flag unchanged; if succeeded,
        // then claimed becomes true and contract balance decreased by exactly 100 (but not below zero).
        // Note: if beforeBal < 100 the withdraw will revert when trying to send, so that case falls into reverted==true
        assert(
            (reverted && afterBal == beforeBal && afterClaimed == beforeClaimed)
            || (!reverted && afterClaimed == true && beforeBal >= 100 && afterBal + 100 == beforeBal)
        );
    }

    receive() external payable {}
}

