    // and whether the call reverts. We will fund c by sending Ether to it, then call getFirstWithdrawalBonus
    // for an address that may be this contract (so we can observe balance change of this test contract).

    // Single public test function taking a recipient and an amount to fund c with.
    function run(address payable recipient, uint fund) public payable {
        require(address(this).balance >= fund);

        // Fund c with 'fund' wei so it can pay out the 100 bonus when withdrawReward is called.
        (bool sent,) = address(c).call{value: fund}("");
        // ignore sent result; property reasons about resulting balances and revert behavior

        uint beforeBalC = address(c).balance;
        uint beforeBalMe = address(this).balance;

        bool reverted;
        try c.getFirstWithdrawalBonus(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBalC = address(c).balance;
        uint afterBalMe = address(this).balance;

        // General rule (observable): Either the call reverted and contract balance is unchanged,
        // or it succeeded and contract balance decreased by exactly 100 and, if recipient == this contract,
