contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept a recipient address and an initial funding amount to deposit into C.
    // The test will fund C (by calling withdrawReward with 0 trick — instead we send ETH directly to C by calling payable fallback: since C has no payable functions, we send ETH using address(c).call{value:...} in this contract constructor? Not allowed. Instead, we require that this contract has funds and forwards them to C via a dummy call: use address(c).call{value: fund}((abi.encodeWithSignature("getFirstWithdrawalBonus(address)", address(this))));
    // But because C.getFirstWithdrawalBonus is public non-payable, sending value will revert. So to fund C we must rely on the checker's deployment which can send ETH to c before run; we therefore simply take fund parameter and require address(this).balance>=fund then transfer to c.

    receive() external payable {}

    function run(address recipient, uint fund) public payable {
        require(address(this).balance >= fund);
        // fund the target contract (if fund > 0) by sending ETH to it
        if (fund > 0) {
            (bool ok, ) = address(c).call{value: fund}("");
            // if this low-level transfer fails, we proceed anyway; ok indicates whether funding succeeded
        }

        // Read observable pre-state
        uint beforeC = address(c).balance;
        uint beforeMe = address(this).balance;

        // Try the call and capture whether it reverted
        bool reverted;
        try c.getFirstWithdrawalBonus(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observable post-state
        uint afterC = address(c).balance;
        uint afterMe = address(this).balance;

        // The intended general rule: if the call did not revert then claimedBonus(recipient) becomes true (observable via attempting a second call which should revert),
        // and the contract never pays out more than 100 in that operation (so c's balance decreases by at most 100 and this contract's balance increases by at most 100).
        // We cannot read claimedBonus directly, so we detect it by attempting a second call: the second call must revert when first succeeded, and may revert initially if first reverted.

        bool secondReverted;
        try c.getFirstWithdrawalBonus(recipient) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        // If first call succeeded, second must revert. If first reverted, second may or may not revert.
        bool claimedObserved = (!reverted && secondReverted);

        // Ensure that if first call succeeded then the decrease in c.balance is <= 100 and increase in this contract's balance is <= 100
        uint deltaC = beforeC >= afterC ? beforeC - afterC : 0;
        uint deltaMe = afterMe >= beforeMe ? afterMe - beforeMe : 0;

        assert( (reverted && true) || (claimedObserved && deltaC <= 100 && deltaMe <= 100) );
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    receive() external payable {}

    // We take a recipient and an amount to fund C so the withdrawal can succeed.
    // The function is payable so the checker can provide funds to this contract before calling run.
    function run(address recipient, uint fund) public payable {
        require(address(this).balance >= fund);

        // Fund the target contract c by sending Ether to it (low-level call). This is a top-level statement.
        (bool fundOk, ) = address(c).call{value: fund}("\x00");
        // fundOk may be false if fallback rejects; still proceed to test behavior under both cases.

        // Observe balances before the call
        uint beforeC = address(c).balance;
        uint beforeMe = address(this).balance;

        // Attempt the first call and record whether it reverted
        bool firstReverted;
        try c.getFirstWithdrawalBonus(recipient) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        // Observe balances after the first call
        uint afterC = address(c).balance;
        uint afterMe = address(this).balance;

        // Attempt a second call to observe whether the bonus was marked claimed (should revert if first succeeded)
        bool secondReverted;
        try c.getFirstWithdrawalBonus(recipient) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        // Compute observed deltas without underflowing inside the assert: use local vars.
        uint deltaC = beforeC >= afterC ? (beforeC - afterC) : 0;
        uint deltaMe = afterMe >= beforeMe ? (afterMe - beforeMe) : 0;

        // General property:
        // If the first call succeeded (firstReverted == false) then:
        //  - the second call must revert (secondReverted == true), i.e. bonus claim becomes single-use observable externally,
        //  - and the contract's balance decreased by at most 100 (the withdrawal cannot pay more than the bonus granted).
        // Otherwise (first call reverted) we make no guarantees about second call or balances.
        assert( firstReverted || (secondReverted && deltaC <= 100) );
    }
}

