contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We'll act as the recipient by having this contract receive ether in the fallback.
    // run takes a recipient flag: if makeRecipientThis==true we pass this contract as recipient,
    // otherwise we pass some other address (an arbitrary non-contract address derived from uint).
    // We also take an amount param to pre-fund rewardsForA by directly calling withdrawReward for that recipient
    // is impossible because rewardsForA is private; instead we rely on getFirstWithdrawalBonus to add 100 and
    // then call withdrawReward. We observe effects by checking address(this).balance and whether calls revert.

    // Note: Because the checker deploys a fresh C and then calls run once, initial claimedBonus is false for all.

    receive() external payable {}

    function run(bool makeRecipientThis, uint otherAddressSeed) public payable {
        require(true);

        address recipient = makeRecipientThis ? address(this) : address(uint160(uint(keccak256(abi.encodePacked(otherAddressSeed, block.timestamp)))));

        // Call getFirstWithdrawalBonus and capture whether it reverts
        bool reverted1;
        try c.getFirstWithdrawalBonus(recipient) {
            reverted1 = false;
        } catch {
            reverted1 = true;
        }

        // After the first call we can observe two behaviors:
        // - If it succeeded: rewardsForA[recipient] should have been added 100 then withdrawn, so c has sent value (possibly 100) to recipient.
        //   For the special case recipient==address(this), address(this).balance should have increased by 100 (since this contract can receive funds).
        // - If it reverted: claimedBonus[recipient] was likely already true (but checker ensures fresh C so revert would indicate other failure).

        // Now call getFirstWithdrawalBonus a second time to check that the bonus can no longer be claimed for the same recipient.
        bool reverted2;
        try c.getFirstWithdrawalBonus(recipient) {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }

        // Observe c._locked via its public getter to ensure no reentrancy lock is left set (SmartFix exposes _locked public)
        bool locked = c._locked();

        // If the first call succeeded then the second must revert (bonus only once), and if recipient==this contract,
        // this contract must have received exactly 100 wei from C (because starting balance of a fresh C is 0 and getFirstWithdrawalBonus
        // increments rewardsForA by 100 then withdraws it). We can't read rewardsForA directly; instead we observe address(this).balance.
        // For general recipient (not this contract) we cannot observe transfer, so we assert only the logical relation between reverts and lock.

        if (!reverted1) {
            // when the first call succeeded, the second must revert (claim only once)
            assert(reverted2 == true && locked == false);
        } else {
            // if first call reverted, then second should also revert (cannot claim later), and no lock must remain
            assert(reverted2 == true && locked == false);
        }
    }
}
